INSERT INTO item(user_id, service_id, equipment_id, quantity, slot_date, start_time, end_time)
SELECT #{userId}, #{serviceId}, #{equipmentId}, #{quantity}, #{date}, #{startTime}, #{endTime}
WHERE NOT EXISTS (
    SELECT 1 FROM item i
    WHERE i.user_id = #{userId}
      AND i.equipment_id = #{equipmentId}
      AND i.slot_date = #{date}
      AND i.start_time = #{startTime}
      AND i.end_time = #{endTime}
      AND i.manage_status = 0
      AND i.create_time > DATE_SUB(NOW(), INTERVAL 60 SECOND)
)

