mapper.select:
SELECT i.order_id, i.user_id, u.name AS username, s.service_name, s.service_describe, s.campus AS campus, i.reason, i.create_time, i.update_time, i.manage_status, c.name AS consultantName, i.slot_date AS slotDate, i.start_time AS startTime, i.end_time AS endTime, e.name AS equipmentName, i.quantity AS quantity, r.name AS roomName FROM item i JOIN user u ON i.user_id = u.id JOIN services s ON i.service_id = s.service_id LEFT JOIN consultant c ON i.consultant_id = c.id LEFT JOIN equipment e ON i.equipment_id = e.id LEFT JOIN room r ON i.room_id = r.id WHERE i.user_id = #{userId}
AND i.manage_status = #{manageStatus}
AND s.service_name LIKE CONCAT('%', #{serviceName}, '%')
ORDER BY i.create_time DESC
